#include "NodeRuntimeRegistry.h"
NodeRuntimeRegistry::NodeRuntimeRegistry():nodes_{},size_(0),locked_(false){}
NodeRuntimeResult NodeRuntimeRegistry::registerNode(const NodeDescriptor& d){if(locked_)return NodeRuntimeResult::REGISTRY_LOCKED;if(!d.isValid())return NodeRuntimeResult::INVALID_NODE;if(findById(d.nodeId()))return NodeRuntimeResult::DUPLICATE_NODE_ID;if(findByAddress(d.address()))return NodeRuntimeResult::DUPLICATE_NODE_ADDRESS;if(size_>=capacity())return NodeRuntimeResult::REGISTRY_FULL;nodes_[size_++]=d;return NodeRuntimeResult::SUCCESS;}
const NodeDescriptor* NodeRuntimeRegistry::findById(NodeId id)const{if(id==INVALID_NODE_ID)return nullptr;for(size_t i=0;i<size_;++i)if(nodes_[i].nodeId()==id)return &nodes_[i];return nullptr;} const NodeDescriptor* NodeRuntimeRegistry::findByAddress(const NodeAddress& a)const{if(!a.isValid())return nullptr;for(size_t i=0;i<size_;++i)if(nodes_[i].address().equals(a))return &nodes_[i];return nullptr;} const NodeDescriptor* NodeRuntimeRegistry::at(size_t i)const{return i<size_?&nodes_[i]:nullptr;} size_t NodeRuntimeRegistry::size()const{return size_;} size_t NodeRuntimeRegistry::capacity()const{return NODE_RUNTIME_MAX_NODES;} bool NodeRuntimeRegistry::isLocked()const{return locked_;} NodeRuntimeResult NodeRuntimeRegistry::lock(){locked_=true;return NodeRuntimeResult::SUCCESS;}
